Overlay[{
  ArrayPlot[vals, ColorFunction -> "TemperatureMap", Mesh -> True],
  Graphics[Table[
    Text[vals[[i, j]], {j - 0.5, Length[vals] - i + 0.5}],
    {i, Length[vals]}, {j, Length[vals[[1]]]}
  ]]
}]
```

