datelistfx = Cases[fxdata, {_, _?NumberQ}];
datelistfx[[All, 1]] = Join[ToExpression@StringSplit[#, "-"], {0, 0, 0.}] & /@ datelistfx[[All, 1]];

DateListPlot[datelistfx, Joined -> True]
