   Table[{{i, j}, binmeans[[i, j]]}, {i, n}, {j, n}],
   1
];

pts2 = Select[pts, Last[#] != 0 &];  (* or use Missing[] instead of 0 *)
f = Interpolation[pts2, InterpolationOrder -> 1];

gTable1 = Table[f[i, j], {i, n}, {j, n}];
