DynamicModule[{run = False, x = 0},
 Column[{
   EventHandler[
    Dynamic@Style["Start evaluation", Blue, Underlined],
    {"MouseClicked" :> (run = True)}
   ],
   Dynamic[
    If[run,
     run = False;
