While[! EndOfFile === (
   data = Read[stream, Riffle[{Word, Word, Number, Number}, Word],
     TokenWords -> {","}] /. {"," -> Sequence[]}),
  Print["Fruit:", data[[1]], " Name:", data[[2]],
    " Integer:", data[[3]], " Real:", data[[4]]];
];

Close[stream];
```

