  {Sin[12 u] Cos[u], Sin[12 u] Sin[u]},
  {u, 0, umax},
  PlotRange -> {-1, 1},
  PerformanceGoal -> "Quality"
 ],
 {umax, 0.1, 2 Pi}
]

This gradually increases the plotted parameter, so the curve appears to be drawn in real time.

If you want manual control, use Manipulate instead of Animate:

Manipulate[
 ParametricPlot[{Sin[12 u] Cos[u], Sin[12 u] Sin[u]}, {u, 0, umax}],
