```wl
r[t_] := {Cos[t], Sin[t], t};
v[t_] := D[r[t], t];

ParametricPlot3D[r[t], {t, 0, 4 Pi},
 Graphics3D[
  Table[
   Arrow[{r[s], r[s] + .4 v[s]}],
   {s, 0, 4 Pi, Pi/8}
  ]
 ]
]
