 Graphics[{
   Circle[],
   Red, PointSize[Large], Point[{Cos[a], Sin[a]}],
   Blue, Rotate[Arrow[{{1, 0}, {1, 1}}], a, {0, 0}]
 }],
 {a, 0, 2 Pi}
]

