tangent[x_, dx_] := {{x - dx, f[x] - f'[x] dx}, {x + dx, f[x] + f'[x] dx}};

Manipulate[
  Plot[f[x], {x, -5, 5},
    Epilog -> {
      Red, PointSize[Large], Point[{x0, f[x0]}],
      Blue, Arrow[{ {x0, f[x0]}, {x0 + 1, f[x0] + f'[x0]} }]
    }
  ],
