dec[n_, k_] := Module[{f = FactorInteger[Binomial[n, k]]},
  {Times @@ (#[[1]]^#[[2]] & /@ Select[f, First[#] <= k &]),
   Times @@ (#[[1]]^#[[2]] & /@ Select[f, First[#] > k &])}
]

